import { readFileSync, statSync } from "node:fs";
import { basename, dirname, join, resolve } from "node:path";
import { ALLOCATION_PORT_BANDS } from "./service-manifest-rules.js";
// This file ships in the npm package as the only dependency of the "main" entry
// (cli/dist/types/index.js). The package check rejects relative imports that the
// tarball does not ship, so these small checkout helpers are kept self-contained
// here instead of importing checkout-id.js (which pulls in the rest of the CLI).
// checkout-id.ts owns the authoritative versions for the running CLI; the bundle
// uses this file, so the two must stay in sync.
const CHECKOUT_NAME_ENV_LOCAL = "FLISK_CHECKOUT_NAME";
const CHECKOUT_ID_RELATIVE_PATH_LOCAL = join(".flisk", ".project-id");
function sanitizeCheckoutNameLocal(rawName) {
    const sanitized = rawName
        .toLowerCase()
        .split(/[^a-z0-9]+/)
        .filter(Boolean)
        .join("-");
    return sanitized || "checkout";
}
function isLinkedGitWorktreeLocal(projectRoot) {
    let dir;
    try {
        dir = resolve(projectRoot);
    }
    catch {
        return false;
    }
    for (;;) {
        const gitPath = join(dir, ".git");
        try {
            const entry = statSync(gitPath);
            // The first `.git` entry is the repository boundary: a `.git` directory is a normal clone.
            if (entry.isDirectory())
                return false;
            return entry.isFile() && readFileSync(gitPath, "utf-8").startsWith("gitdir:");
        }
        catch {
            // No .git here (or unreadable): keep walking, as git does.
        }
        const parent = dirname(dir);
        if (parent === dir)
            return false;
        dir = parent;
    }
}
function getCheckoutNameLocal(projectRoot) {
    return sanitizeCheckoutNameLocal(basename(resolve(projectRoot)));
}
function readCheckoutHostSuffixLocal(projectRoot) {
    try {
        const raw = readFileSync(join(projectRoot, CHECKOUT_ID_RELATIVE_PATH_LOCAL), "utf-8").trim();
        if (!raw.startsWith("{"))
            return null;
        const parsed = JSON.parse(raw);
        return typeof parsed.hostSuffix === "string" && parsed.hostSuffix.length > 0
            ? parsed.hostSuffix
            : null;
    }
    catch {
        return null;
    }
}
